from qlib import Q
C='face-color-analysis'
Q(C,'basic',"표준형 얼굴의 세로 비율을 3등분할 때 나누는 기준으로 알맞은 것은?","헤어라인~눈썹, 눈썹~코끝, 코끝~턱끝",[("헤어라인~눈, 눈~입술, 입술~턱끝","눈과 입술이 아니라 눈썹과 코끝을 기준으로 나눕니다."),("정수리~이마, 이마~코끝, 코끝~턱끝","정수리가 아니라 헤어라인부터 잽니다."),("헤어라인~코끝, 코끝~입술, 입술~턱끝","세 부분의 길이가 같지 않게 나뉩니다.")],"얼굴 세로 3등분 = 헤어라인·눈썹·코끝·턱끝","표준형(계란형) 얼굴은 세로로 **헤어라인~눈썹, 눈썹~코끝, 코끝~턱끝**이 거의 같은 길이로 3등분됩니다. 가로는 눈 하나의 폭을 기준으로 약 5등분합니다.",4,["얼굴 비율"])
Q(C,'intermediate',"표준형 얼굴의 가로 비율에서 두 눈 사이의 거리는 대체로 무엇과 같은가?","눈 하나의 가로 길이",[("코의 세로 길이","가로 비율은 눈 폭을 기준으로 합니다."),("입술의 세로 두께","입술 두께와는 관계가 없습니다."),("눈 두 개를 합친 길이","너무 넓습니다.")],"얼굴 가로 5등분 = 눈 하나 폭 기준","표준형 얼굴은 가로로 눈 하나의 폭을 기준으로 약 **5등분**되며, **두 눈 사이의 거리는 눈 하나의 길이**와 비슷합니다. 이보다 넓으면 눈 사이가 먼 눈, 좁으면 가까운 눈으로 봅니다.",4,["얼굴 비율"])
Q(C,'basic',"메이크업에서 하이라이트를 주는 목적으로 가장 알맞은 것은?","밝은 색으로 그 부분이 넓고 도드라져 보이게 한다",[("어두운 색으로 그 부분이 들어가 보이게 한다","이는 셰이딩의 목적입니다."),("피부의 붉은 기를 감춘다","붉은 기는 녹색 계열 베이스나 컨실러로 보정합니다."),("입술 윤곽을 뚜렷하게 한다","이는 립 라이너의 역할입니다.")],"하이라이트 = 밝게·도드라짐 / 셰이딩 = 어둡게·들어가 보임","**하이라이트**는 피부보다 밝은 색으로 이마·콧등 등을 **도드라지고 넓어 보이게** 합니다. **셰이딩**은 어두운 색으로 턱선·볼 아래 등을 **들어가고 좁아 보이게** 해 윤곽을 다듬습니다.",5,["윤곽 수정"])
Q(C,'intermediate',"둥근형 얼굴을 갸름하게 보이도록 수정하는 방법으로 가장 알맞은 것은?","양쪽 볼 옆과 턱선에 셰이딩을 하고, 이마 중앙과 콧등에 세로로 하이라이트를 준다",[("이마 위쪽과 턱 끝에 셰이딩을 한다","이는 긴 얼굴을 짧아 보이게 하는 방법입니다."),("양 볼에 가로로 둥글게 블러셔를 넓게 펴 바른다","얼굴이 더 둥글어 보입니다."),("턱의 각진 부분에만 셰이딩을 한다","이는 각진 얼굴의 수정 방법입니다.")],"둥근형 = 양옆 셰이딩 + 세로 하이라이트","**둥근형** 얼굴은 가로 폭이 넓어 보이므로 **양 볼 옆·턱선에 셰이딩**을 하고 이마·콧등·턱 끝에 **세로로 하이라이트**를 주어 길어 보이게 합니다. 블러셔는 광대뼈 아래에서 사선으로 넣습니다.",5,["윤곽 수정"])
Q(C,'intermediate',"긴 얼굴형을 수정하는 메이크업으로 가장 알맞은 것은?","이마 위쪽과 턱 끝에 셰이딩을 하고 블러셔는 가로로 넣는다",[("콧등에 길게 세로 하이라이트를 준다","얼굴이 더 길어 보입니다."),("블러셔를 광대뼈에서 입꼬리 쪽으로 세로로 길게 넣는다","세로 방향은 얼굴을 더 길어 보이게 합니다."),("양 볼 옆에 진하게 셰이딩을 한다","폭이 좁아져 더 길어 보입니다.")],"긴형 = 위아래 셰이딩 + 가로 블러셔","**긴 얼굴형**은 **이마 위쪽(헤어라인)과 턱 끝에 셰이딩**을 해 길이를 줄이고, 블러셔와 하이라이트를 **가로 방향**으로 넣어 폭이 넓어 보이게 합니다.",4,["윤곽 수정"])
Q(C,'advanced',"각진(사각형) 얼굴의 윤곽 수정으로 가장 알맞은 것은?","턱의 각진 부분에 셰이딩을 하여 부드럽게 보이게 한다",[("턱 끝과 이마 위쪽에만 셰이딩을 한다","이는 긴 얼굴형의 수정 방법입니다."),("이마 양옆에만 셰이딩을 하고 턱은 밝게 한다","이는 역삼각형 얼굴의 수정 방법입니다."),("턱의 각진 부분에 하이라이트를 준다","각진 부분이 더 도드라집니다.")],"각진형 = 턱 각 셰이딩으로 부드럽게","**각진(사각형) 얼굴**은 **양쪽 턱의 각진 부분에 셰이딩**을 하여 둥글고 부드럽게 보이게 합니다. 눈썹과 입술도 각지지 않게 곡선으로 표현합니다.",4,["윤곽 수정"])
Q(C,'basic',"먼셀 색 체계에서 색의 3속성으로 바르게 짝지은 것은?","색상·명도·채도",[("색상·명도·온도","온도감은 색의 느낌이지 3속성이 아닙니다."),("명도·채도·광택","광택은 3속성이 아닙니다."),("색상·채도·투명도","투명도는 3속성이 아닙니다.")],"색의 3속성 = 색상·명도·채도","색의 3속성은 색의 이름인 **색상**, 밝고 어두운 정도인 **명도**, 맑고 탁한 정도(선명함)인 **채도**입니다.",5,["메이크업 색채"])
Q(C,'basic',"색상환에서 서로 마주 보고 있어 섞으면 무채색에 가까워지는 두 색의 관계는?","보색",[("유사색","유사색은 색상환에서 서로 가까이 있는 색입니다."),("동일색","동일색은 같은 색상에서 명도·채도만 다른 색입니다."),("난색","난색은 따뜻한 느낌의 색입니다.")],"보색 = 색상환 맞은편, 서로 중화","**보색**은 색상환에서 맞은편에 있는 색으로, 섞으면 무채색에 가까워집니다. 그래서 붉은 잡티에는 보색인 **녹색** 계열 베이스나 컨실러를 써서 붉은 기를 줄입니다.",5,["메이크업 색채"])
Q(C,'intermediate',"얼굴의 붉은 기를 중화하기 위해 메이크업 베이스(컬러 코렉터)로 가장 알맞은 색은?","녹색",[("분홍색","분홍색은 창백한 피부에 생기를 줄 때 씁니다."),("보라색","보라색은 노란 기를 줄일 때 씁니다."),("주황색","주황색은 푸른 기의 다크서클을 가릴 때 씁니다.")],"붉은 기 = 녹색 / 노란 기 = 보라 / 창백 = 분홍","컬러 코렉터는 보색 관계를 이용합니다. **붉은 기에는 녹색**, 노란 기에는 보라색(라벤더), 창백한 피부에는 분홍색, 푸르스름한 다크서클에는 주황·살구색을 씁니다.",5,["컬러 코렉팅"])
Q(C,'intermediate',"퍼스널 컬러 진단에서 따뜻한 느낌의 웜 톤에 어울리는 색으로 가장 알맞은 것은?","노란 기가 도는 코럴·오렌지·골드 계열",[("푸른 기가 도는 핑크·라벤더·실버 계열","이는 쿨 톤에 어울리는 색입니다."),("회색에 가까운 블루 계열","차가운 계열은 쿨 톤에 어울립니다."),("푸른빛이 도는 와인·버건디 계열","쿨 톤에 어울리는 색입니다.")],"웜 톤 = 노란 기(골드·코럴) / 쿨 톤 = 푸른 기(실버·핑크)","**웜 톤**은 피부에 노란 기가 돌아 **코럴·오렌지·골드** 같은 노란 기 바탕의 색이 잘 어울리고, **쿨 톤**은 푸른 기가 돌아 **핑크·라벤더·실버** 같은 푸른 기 바탕의 색이 잘 어울립니다.",4,["퍼스널 컬러"])
Q(C,'advanced',"퍼스널 컬러의 사계절 유형 가운데 쿨 톤에 속하는 것끼리 바르게 짝지은 것은?","여름·겨울",[("봄·가을","봄과 가을은 웜 톤입니다."),("봄·겨울","봄은 웜 톤입니다."),("가을·여름","가을은 웜 톤입니다.")],"봄·가을 = 웜 / 여름·겨울 = 쿨","사계절 퍼스널 컬러에서 **봄·가을은 웜 톤**, **여름·겨울은 쿨 톤**입니다. 봄은 밝고 맑은 색, 여름은 부드럽고 흐린 색, 가을은 깊고 차분한 색, 겨울은 선명하고 대비가 강한 색이 어울립니다.",4,["퍼스널 컬러"],lock=True)
Q(C,'advanced',"따뜻한 느낌을 주며 앞으로 나와 보이는 진출색의 성질이 있는 색은?","빨강·주황 계열의 난색",[("파랑·청록 계열의 한색","한색은 차갑고 뒤로 물러나 보이는 후퇴색입니다."),("명도가 낮은 회색","어두운 무채색은 후퇴해 보입니다."),("채도가 낮은 남색","남색은 차가운 계열입니다.")],"난색 = 따뜻·진출·팽창 / 한색 = 차가움·후퇴·수축","빨강·주황·노랑 같은 **난색**은 따뜻하고 **앞으로 나와 보이며**(진출색) 크게 보입니다. 파랑·청록 같은 **한색**은 차갑고 **뒤로 물러나 보입니다**(후퇴색). 셰이딩에 어두운 색을 쓰는 것도 후퇴해 보이는 성질을 이용한 것입니다.",3,["메이크업 색채"])
C='base-makeup'
Q(C,'basic',"건성 피부의 메이크업 전 기초 손질로 가장 알맞은 것은?","보습력이 좋은 크림으로 충분히 수분과 유분을 채운다",[("알코올이 많은 수렴 화장수를 여러 번 바른다","알코올은 수분을 날려 더 건조하게 합니다."),("유분 조절용 파우더를 먼저 바른다","건성 피부에는 유분 조절이 필요하지 않습니다."),("기초화장품 없이 바로 파운데이션을 바른다","들뜨고 각질이 부각됩니다.")],"건성 = 보습 크림 충분히","**건성 피부**는 수분·유분이 부족해 베이스가 들뜨기 쉬우므로, 보습 화장수와 **보습력 좋은 크림**으로 충분히 채운 뒤 메이크업을 합니다. 지성 피부는 산뜻한 제품과 유분 조절 제품을 씁니다.",4,["기초화장품"])
Q(C,'basic',"메이크업 베이스의 역할로 가장 알맞은 것은?","피부 톤을 정돈하고 파운데이션이 잘 밀착되게 한다",[("얼굴에 입체감을 주는 셰이딩을 한다","셰이딩은 윤곽 수정 단계에서 합니다."),("눈썹의 모양을 잡는다","눈썹은 아이브로우 제품으로 그립니다."),("화장을 지운다","화장을 지우는 것은 클렌징 제품입니다.")],"메이크업 베이스 = 톤 정돈·밀착·보호","**메이크업 베이스**는 피부색을 고르게 정돈하고, 파운데이션이 **잘 밀착**되며 오래 가게 하고, 피부를 보호하는 역할을 합니다.",4,["베이스 제품"])
Q(C,'intermediate',"리퀴드 파운데이션에 대한 설명으로 알맞은 것은?","수분이 많아 가볍고 자연스럽게 표현되지만 커버력은 크림 타입보다 약한 편이다",[("유분이 가장 많아 커버력이 가장 높다","커버력이 가장 높은 것은 스틱·크림 타입입니다."),("가루 형태라서 유분을 흡수한다","가루 형태는 파우더 파운데이션입니다."),("무대 분장에만 쓴다","일상 메이크업에 널리 씁니다.")],"리퀴드 = 가볍고 자연스러움 / 크림·스틱 = 커버력 높음","**리퀴드 파운데이션**은 수분이 많아 잘 펴지고 **가볍고 자연스러운** 피부 표현에 좋습니다. 잡티를 많이 가려야 할 때는 커버력이 높은 **크림·스틱** 타입을 씁니다.",4,["베이스 제품"])
Q(C,'intermediate',"파운데이션 색을 고를 때 피부색과 맞는지 확인하기에 가장 알맞은 부위는?","턱선(얼굴과 목의 경계)",[("손등","손등은 얼굴과 색이 다른 경우가 많습니다."),("이마 한가운데","얼굴과 목의 색 차이를 확인하기 어렵습니다."),("손바닥","손바닥은 얼굴색과 많이 다릅니다.")],"파운데이션 색 = 턱선에서 테스트","파운데이션은 얼굴과 목의 색이 자연스럽게 이어져야 하므로 **턱선(얼굴과 목의 경계)**에 발라 보고 고릅니다.",4,["베이스 제품"])
Q(C,'basic',"메이크업 스펀지로 파운데이션을 바르는 방법으로 가장 알맞은 것은?","얼굴 안쪽에서 바깥쪽으로 두드리듯 펴 바른다",[("바깥쪽에서 안쪽으로 세게 문지른다","경계가 생기고 피부가 자극을 받습니다."),("한 부위에 두껍게 얹어 그대로 둔다","뭉치고 들뜹니다."),("눈가와 입가에 가장 두껍게 바른다","움직임이 많은 부위는 얇게 바릅니다.")],"베이스 = 안→밖, 두드려 얇게","파운데이션은 얼굴 **안쪽에서 바깥쪽**으로 펴 바르고, 스펀지로 **두드리듯** 밀착시킵니다. 눈가·입가처럼 움직임이 많은 곳은 얇게 바릅니다.",4,["베이스 도구"])
Q(C,'intermediate',"눈 밑의 푸르스름한 다크서클을 가리는 컨실러로 가장 알맞은 색은?","주황(살구)빛이 도는 컨실러",[("녹색 컨실러","녹색은 붉은 기를 가립니다."),("보라색 컨실러","보라색은 노란 기를 줄입니다."),("흰색 하이라이터","흰색은 회색빛으로 뜰 수 있습니다.")],"푸른 다크서클 = 주황·살구 계열","푸르스름한 다크서클에는 그 보색에 가까운 **주황·살구** 계열 컨실러를 바르면 자연스럽게 가려집니다.",4,["피부 결점 보완"])
Q(C,'advanced',"베이스 메이크업 순서로 가장 알맞은 것은?","기초화장품 → 메이크업 베이스 → 파운데이션 → 컨실러 → 파우더",[("파우더 → 파운데이션 → 메이크업 베이스 → 컨실러","파우더는 맨 마지막에 바릅니다."),("파운데이션 → 기초화장품 → 파우더 → 메이크업 베이스","기초화장품이 가장 먼저입니다."),("컨실러 → 파우더 → 메이크업 베이스 → 파운데이션","파우더를 먼저 바르면 파운데이션이 뭉칩니다.")],"기초 → 베이스 → 파운데이션 → 컨실러 → 파우더","베이스 메이크업은 **기초화장품 → 메이크업 베이스 → 파운데이션 → 컨실러 → 파우더** 순서가 기본입니다. 컨실러는 리퀴드 파운데이션 다음에 쓰는 것이 일반적이며, 파우더로 유분을 잡고 고정합니다.",4,["베이스 순서"],lock=True)
Q(C,'intermediate',"파우더의 역할로 가장 거리가 먼 것은?","피부에 유분과 수분을 공급한다",[("파운데이션을 고정해 화장이 오래가게 한다","파우더의 대표 역할입니다."),("번들거림을 줄인다","유분을 흡수해 번들거림을 줄입니다."),("피부를 보송하고 매끈하게 표현한다","파우더의 역할입니다.")],"파우더 = 고정·유분 흡수 (보습 X)","**파우더**는 파운데이션을 **고정**하고 **유분을 흡수**해 번들거림을 막으며 보송한 피부를 표현합니다. 유분·수분 공급은 기초화장품의 역할입니다.",4,["베이스 제품"],lock=True)
Q(C,'advanced',"민감한 피부에 메이크업을 할 때 가장 알맞은 방법은?","사용할 제품을 귀 뒤나 팔 안쪽에 먼저 발라 반응을 확인한다(패치 테스트)",[("향이 강한 제품을 써서 기분을 좋게 한다","향료는 자극이 될 수 있습니다."),("스크럽으로 각질을 강하게 문질러 제거한다","강한 자극은 민감한 피부를 악화시킵니다."),("알코올 함량이 높은 제품을 쓴다","알코올은 자극과 건조를 일으킬 수 있습니다.")],"민감성 = 패치 테스트, 저자극 제품","**민감성 피부**는 새 제품을 쓰기 전에 귀 뒤나 팔 안쪽에 발라 보는 **패치 테스트**로 반응을 확인하고, 향료·알코올이 적은 저자극 제품을 씁니다.",4,["피부 유형별 기초"])
